INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'North Node', 'quincunx', 'Góc chiếu Quincunx giữa Moon và North Node thể hiện sự tương tác năng lượng giữa hai hành tinh Moon và North Node.', 'Trong cuộc sống hàng ngày, góc chiếu này tạo ra sự kết nối trực tiếp giữa năng lượng Moon và biểu hiện của North Node.', 'Khả năng thích ứng cao, thấu hiểu tâm lý và phát huy sức mạnh tổng hợp từ Moon và North Node.', 'Cần học cách cân bằng và hòa hợp nhu cầu của Moon và North Node để tránh xung đột nội tâm.', '', '', ARRAY['Moon', 'North Node', 'quincunx']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO NOTHING;
